// ── Demo A: multibit staircase ───────────────────────────────────────
(function(){
  var c=document.getElementById('stairCanvas'); if(!c) return;
  var ctx=c.getContext('2d'), bits=document.getElementById('stairBits'), lbl=document.getElementById('stairN');
  var W=c.width, H=c.height, mid=H/2, amp=H*0.40, cycles=2, samples=48;
  function draw(){
    var N=+bits.value, L=Math.pow(2,N), maxv=L/2-1;
    lbl.textContent=N+'-bit · '+L.toLocaleString()+' levels';
    ctx.clearRect(0,0,W,H);
    if(N<=5){ ctx.strokeStyle='#efe6d8'; ctx.lineWidth=1; for(var k=-maxv;k<=maxv;k++){ var yy=mid-(k/maxv)*amp; ctx.beginPath(); ctx.moveTo(0,yy); ctx.lineTo(W,yy); ctx.stroke(); } }
    ctx.strokeStyle='#cbb89e'; ctx.lineWidth=1.5; ctx.beginPath();
    for(var x=0;x<=W;x++){ var t=x/W*cycles*2*Math.PI, y=mid-Math.sin(t)*amp; x?ctx.lineTo(x,y):ctx.moveTo(x,y); }
    ctx.stroke();
    ctx.strokeStyle='#a8541f'; ctx.lineWidth=2; ctx.beginPath();
    for(var i=0;i<samples;i++){ var s=Math.sin(i/samples*cycles*2*Math.PI), q=Math.round(s*maxv)/maxv, x0=i/samples*W, x1=(i+1)/samples*W, yq=mid-q*amp; i?ctx.lineTo(x0,yq):ctx.moveTo(x0,yq); ctx.lineTo(x1,yq); }
    ctx.stroke();
  }
  bits.addEventListener('input',draw); draw();
})();

// ── Demo B: delta-sigma noise shaping (real DFT) ──────────────────────
(function(){
  var c=document.getElementById('nsCanvas'); if(!c) return;
  var ctx=c.getContext('2d'), btn=document.getElementById('nsToggle'), info=document.getElementById('nsInfo');
  var W=c.width, H=c.height, N=512, shape=true, BITS=3;
  function clamp(v){ return v>1?1:(v<-1?-1:v); }
  function spectrum(){
    var maxv=Math.pow(2,BITS)/2-1, k0=6, y=new Array(N), e=0;
    for(var n=0;n<N;n++){
      var s=0.7*Math.sin(2*Math.PI*k0*n/N), q;
      if(shape){ var w=s-e; q=clamp(Math.round(w*maxv)/maxv); e=q-w; }
      else { q=clamp(Math.round(s*maxv)/maxv); }
      y[n]=q;
    }
    var half=N/2, mag=new Array(half);
    for(var k=0;k<half;k++){ var re=0,im=0; for(var m=0;m<N;m++){ var a=2*Math.PI*k*m/N; re+=y[m]*Math.cos(a); im-=y[m]*Math.sin(a); } mag[k]=Math.sqrt(re*re+im*im)/N; }
    return mag;
  }
  function draw(){
    info.textContent=BITS+'-bit quantizer, '+(shape?'1st-order shaping':'no shaping');
    btn.textContent='noise shaping: '+(shape?'ON':'OFF');
    var mag=spectrum(), half=mag.length, band=Math.floor(half*0.25);
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#f3ece1'; ctx.fillRect(0,0,band/half*W,H);
    var top=0, bot=-120;
    function py(db){ return H-((db-bot)/(top-bot))*H; }
    ctx.strokeStyle=shape?'#a8541f':'#8a93a0'; ctx.lineWidth=1.5; ctx.beginPath();
    for(var k=0;k<half;k++){ var x=k/half*W, db=20*Math.log10(mag[k]+1e-9), yy=py(db); k?ctx.lineTo(x,yy):ctx.moveTo(x,yy); }
    ctx.stroke();
  }
  btn.addEventListener('click',function(){ shape=!shape; draw(); }); draw();
})();

// ── Demo C: hear the bit depth (Web Audio, user gesture) ──────────────
(function(){
  var wrap=document.getElementById('hearBtns'); if(!wrap) return; var actx=null;
  wrap.addEventListener('click',function(ev){
    var b=ev.target.closest&&ev.target.closest('button[data-bits]'); if(!b) return;
    var bits=+b.getAttribute('data-bits');
    try{ actx=actx||new (window.AudioContext||window.webkitAudioContext)(); }catch(e){ return; }
    if(actx.resume) actx.resume();
    var sr=actx.sampleRate, len=Math.floor(sr*1.1), buf=actx.createBuffer(1,len,sr), ch=buf.getChannelData(0);
    var maxv=Math.pow(2,bits)/2-1, f=440;
    for(var i=0;i<len;i++){
      var env=Math.min(1, i/(sr*0.02), (len-i)/(sr*0.06)), s=Math.sin(2*Math.PI*f*i/sr)*0.25;
      ch[i]=(maxv>0?Math.round(s*maxv)/maxv:0)*env;
    }
    var src=actx.createBufferSource(); src.buffer=buf; src.connect(actx.destination); src.start();
  });
})();
// ── Demo: the R-2R ladder (binary weighting + why precision matters) ──
// An N-bit voltage-mode R-2R ladder. Each bit i contributes Vref * 2^i / 2^N,
// so the MSB is half of Vref, the next a quarter, and so on, built from just
// two resistor values. A tolerance on those resistors perturbs each bit's
// weight; errors in the big bits bend the transfer curve and can break
// monotonicity (a higher code yields a lower voltage), the failure a real
// ladder must engineer away. Per-bit error directions are fixed so the slider
// only scales them.
(function(){
  var wrap = document.getElementById('ladderBits'); if (!wrap) return;
  var out = document.getElementById('ladderOut'), tol = document.getElementById('ladderTol'), tolL = document.getElementById('ladderTolL');
  var xfer = document.getElementById('ladderXfer'), xctx = xfer && xfer.getContext('2d');
  var N = 6, MAX = (1 << N) - 1, code = 1 << (N - 1);
  var dir = [0.7, -0.9, 0.4, -0.6, 0.85, -0.3]; // fixed error direction per bit (index = bit i, LSB..MSB)
  var html = '';
  for (var b = N - 1; b >= 0; b--) html += '<button class="dac-bit" type="button" data-b="' + b + '" aria-pressed="false">b' + b + '<span>Vref/' + Math.pow(2, N - b) + '</span></button>';
  wrap.innerHTML = html;
  function weights(t) { var w = []; for (var i = 0; i < N; i++) w[i] = (Math.pow(2, i) / Math.pow(2, N)) * (1 + dir[i] * t); return w; }
  function vout(c, w) { var v = 0; for (var i = 0; i < N; i++) if (c & (1 << i)) v += w[i]; return v; }
  function render() {
    var t = (+tol.value) / 100; if (tolL) tolL.textContent = (+tol.value).toFixed(1) + '%';
    var w = weights(t);
    if (out) out.textContent = 'Vout = ' + vout(code, w).toFixed(3) + ' Vref   (code ' + code + ' of ' + MAX + ')';
    var btns = wrap.querySelectorAll('.dac-bit');
    for (var k = 0; k < btns.length; k++) { var bb = +btns[k].getAttribute('data-b'); btns[k].setAttribute('aria-pressed', (code & (1 << bb)) ? 'true' : 'false'); }
    if (!xctx) return;
    var W = xfer.width, H = xfer.height; xctx.clearRect(0, 0, W, H);
    xctx.strokeStyle = '#cbb89e'; xctx.lineWidth = 1.2; xctx.beginPath();
    for (var c = 0; c <= MAX; c++) { var x = 5 + c / MAX * (W - 10), y = H - 5 - (c / MAX) * (H - 10); c ? xctx.lineTo(x, y) : xctx.moveTo(x, y); }
    xctx.stroke();
    var vfull = vout(MAX, w) || 1, px = null, pv = 0;
    for (var c2 = 0; c2 <= MAX; c2++) {
      var v = vout(c2, w), X = 5 + c2 / MAX * (W - 10), Y = H - 5 - (v / vfull) * (H - 10);
      if (px) { var nm = v < pv - 1e-9; xctx.strokeStyle = nm ? '#c0392b' : '#a8541f'; xctx.lineWidth = nm ? 2.4 : 1.6; xctx.beginPath(); xctx.moveTo(px.x, px.y); xctx.lineTo(X, Y); xctx.stroke(); }
      px = { x: X, y: Y }; pv = v;
    }
  }
  wrap.addEventListener('click', function(e) { var b = e.target.closest && e.target.closest('.dac-bit'); if (!b) return; code ^= (1 << +b.getAttribute('data-b')); render(); });
  if (tol) tol.addEventListener('input', render);
  render();
})();

// ── Demo: the reconstruction filter, a time vs frequency tradeoff ─────
// A windowed-sinc reconstruction filter. Raising the tap count sharpens the
// frequency roll-off near Nyquist but lengthens the impulse response, so the
// ringing in time grows. You cannot be arbitrarily sharp in both domains: that
// is the Fourier uncertainty tradeoff that NOS, oversampling, apodizing, and
// closed-form filters each answer differently.
(function(){
  var sh = document.getElementById('filtSharp'); if (!sh) return;
  var shL = document.getElementById('filtSharpL');
  var tC = document.getElementById('filtTime'), fC = document.getElementById('filtFreq');
  var tctx = tC && tC.getContext('2d'), fctx = fC && fC.getContext('2d');
  function sinc(x) { return x === 0 ? 1 : Math.sin(Math.PI * x) / (Math.PI * x); }
  function build(s) {
    var L = Math.round(7 + s * 7) * 2 + 1, c = (L - 1) / 2, fc = 0.45, h = [];
    for (var n = 0; n < L; n++) {
      var win = 0.5 - 0.5 * Math.cos(2 * Math.PI * n / (L - 1)); // Hann
      h.push(sinc(2 * fc * (n - c)) * win);
    }
    return h;
  }
  function dft(h, M) {
    var mag = [];
    for (var k = 0; k < M; k++) {
      var re = 0, im = 0, f = 0.5 * k / (M - 1); // 0..Nyquist
      for (var n = 0; n < h.length; n++) { var a = 2 * Math.PI * f * n; re += h[n] * Math.cos(a); im -= h[n] * Math.sin(a); }
      mag.push(Math.sqrt(re * re + im * im));
    }
    var peak = Math.max.apply(null, mag) || 1;
    return mag.map(function(m) { return m / peak; });
  }
  function draw() {
    var s = +sh.value; if (shL) shL.textContent = (s < 3 ? 'gentle' : s < 6 ? 'medium' : 'sharp') + ' (' + (Math.round(7 + s * 7) * 2 + 1) + ' taps)';
    var h = build(s);
    if (tctx) {
      var W = tC.width, H = tC.height, mid = H / 2; tctx.clearRect(0, 0, W, H);
      tctx.strokeStyle = '#efe6d8'; tctx.beginPath(); tctx.moveTo(0, mid); tctx.lineTo(W, mid); tctx.stroke();
      tctx.strokeStyle = '#a8541f'; tctx.lineWidth = 1.6; tctx.beginPath();
      for (var n = 0; n < h.length; n++) { var x = n / (h.length - 1) * W, y = mid - h[n] * (H * 0.40); n ? tctx.lineTo(x, y) : tctx.moveTo(x, y); }
      tctx.stroke();
    }
    if (fctx) {
      var W2 = fC.width, H2 = fC.height, mag = dft(h, 160); fctx.clearRect(0, 0, W2, H2);
      fctx.fillStyle = '#f3ece1'; fctx.fillRect(0, 0, 0.9 * W2, H2); // passband shade to ~0.45 Nyquist
      fctx.strokeStyle = '#a8541f'; fctx.lineWidth = 1.6; fctx.beginPath();
      for (var k = 0; k < mag.length; k++) { var db = 20 * Math.log10(mag[k] + 1e-6), x2 = k / (mag.length - 1) * W2, y2 = H2 - ((db + 80) / 80) * H2; k ? fctx.lineTo(x2, y2) : fctx.moveTo(x2, y2); }
      fctx.stroke();
    }
  }
  sh.addEventListener('input', draw); draw();
})();

// ── Demo: the contested ground — low-level linearity, multibit vs delta-sigma ──
// Where the "musicality" argument actually lives: a QUIET tone (the soft tail of a
// note), where only the lowest bits are working. Multibit rounds to its nearest
// exact level, which at low level bends the wave into harmonic DISTORTION. Delta-
// sigma keeps the average level honest but rides a shaped NOISE floor. Same tone,
// two flavors of imperfection, shown as spectra and playable. Crank the bits toward
// 16 and both fall below hearing: the honest reason the debate never settles.
(function(){
  var bits = document.getElementById('muBits'); if (!bits) return;
  var bitsL = document.getElementById('muBitsL');
  var mbC = document.getElementById('muMbCanvas'), dsC = document.getElementById('muDsCanvas');
  var mbCtx = mbC && mbC.getContext('2d'), dsCtx = dsC && dsC.getContext('2d');
  var mbInfo = document.getElementById('muMbInfo'), dsInfo = document.getElementById('muDsInfo');
  var N = 512, K0 = 5, AMP = 0.08, actx = null; // a quiet tone at bin K0
  function clamp(v){ return v > 1 ? 1 : v < -1 ? -1 : v; }
  function quantize(B, shape){
    var maxv = Math.pow(2, B - 1) - 1, y = new Array(N), e = 0;
    for (var n = 0; n < N; n++){
      var x = AMP * Math.sin(2 * Math.PI * K0 * n / N), q;
      if (shape){ var w = x - e; q = clamp(Math.round(w * maxv) / maxv); e = q - w; }
      else { q = clamp(Math.round(x * maxv) / maxv); }
      y[n] = q;
    }
    return y;
  }
  function spectrum(y){
    var half = N / 2, mag = new Array(half);
    for (var k = 0; k < half; k++){ var re = 0, im = 0; for (var n = 0; n < N; n++){ var a = 2 * Math.PI * k * n / N; re += y[n] * Math.cos(a); im -= y[n] * Math.sin(a); } mag[k] = Math.sqrt(re * re + im * im) / N; }
    return mag;
  }
  function drawSpec(ctx, C, mag, accent){
    var W = C.width, H = C.height, half = mag.length;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#f3ece1'; ctx.fillRect((K0 - 1) / half * W, 0, 3 / half * W, H); // tone band
    function py(db){ return H - ((db + 120) / 120) * H; }
    ctx.strokeStyle = accent; ctx.lineWidth = 1.4; ctx.beginPath();
    for (var k = 0; k < half; k++){ var x = k / half * W, db = 20 * Math.log10(mag[k] + 1e-9), y = py(db); k ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
    ctx.stroke();
  }
  function render(){
    var B = +bits.value; if (bitsL) bitsL.textContent = B + '-bit';
    var sm = spectrum(quantize(B, false)), sd = spectrum(quantize(B, true));
    if (mbCtx) drawSpec(mbCtx, mbC, sm, '#a8541f');
    if (dsCtx) drawSpec(dsCtx, dsC, sd, '#2f6fd0');
    var harm = 0; for (var h = 2; h * K0 < N / 2; h++) harm += sm[h * K0] * sm[h * K0];      // multibit distortion
    var noise = 0; for (var k = 1; k < N / 2; k++){ if (Math.abs(k - K0) <= 1) continue; noise += sd[k] * sd[k]; } // ds noise
    if (mbInfo) mbInfo.textContent = harm > 2e-6 ? 'harmonic distortion' : 'clean';
    if (dsInfo) dsInfo.textContent = noise > 2e-6 ? 'shaped noise floor' : 'clean';
  }
  function play(shape){
    try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return; }
    if (actx.resume) actx.resume();
    var B = +bits.value, sr = actx.sampleRate, len = Math.floor(sr * 1.3), buf = actx.createBuffer(1, len, sr), ch = buf.getChannelData(0);
    var maxv = Math.pow(2, B - 1) - 1, f = 440, e = 0;
    for (var i = 0; i < len; i++){
      var env = Math.min(1, i / (sr * 0.02), (len - i) / (sr * 0.06)), x = AMP * Math.sin(2 * Math.PI * f * i / sr), q;
      if (shape){ var w = x - e; q = clamp(Math.round(w * maxv) / maxv); e = q - w; }
      else { q = clamp(Math.round(x * maxv) / maxv); }
      ch[i] = q * env * 2.2; // gain the quiet tone up so the imperfection is audible (kept gentle)
    }
    var s = actx.createBufferSource(); s.buffer = buf; s.connect(actx.destination); s.start();
  }
  bits.addEventListener('input', render);
  var grid = document.querySelector('.mu-grid');
  if (grid) grid.addEventListener('click', function(ev){ var b = ev.target.closest && ev.target.closest('[data-topo]'); if (b) play(b.getAttribute('data-topo') === 'ds'); });
  render();
})();
